WITH with_windows AS (SELECT *, AVG(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS budget_avg_5_prior, FIRST_VALUE(budget) IGNORE NULLS OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_budget FROM departments) SELECT dept_name, location, CASE WHEN budget_avg_5_prior >= 4413928 THEN 'HIGH' ELSE 'LOW' END AS budget_avg_5_prior_tier, SORT_ARRAY(COLLECT_SET(dept_name)) AS dept_name_list, AVG(first_known_budget) AS avg_first_known_budget, COUNT(*) AS cnt, COUNT(CASE WHEN dept_name = 'Engineering' THEN 1 END) AS engineering_count, SORT_ARRAY(COLLECT_SET(dept_name)) AS dept_name_list_2 FROM with_windows GROUP BY dept_name, location, CASE WHEN budget_avg_5_prior >= 4413928 THEN 'HIGH' ELSE 'LOW' END ORDER BY location NULLS LAST
